package cl.nexbyte.siger.institucional.nucleo;
import cl.nexbyte.siger.institucional.documental.*;import cl.nexbyte.siger.institucional.robustez.FalloTecnico;
import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import java.io.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
class AsociacionesDocumentalesTest {
 @TempDir Path temp;DocumentosReqFixture x;DocumentosGestion casos;AsociacionesDocumentales service;
 @BeforeEach void setup()throws Exception{x=new DocumentosReqFixture(temp,null,"_asoc");casos=new DocumentosGestion(x.d.db,x.files,new AutorizacionNucleo(x.f.core),p->true,x.inspector,x.clock);service=new AsociacionesDocumentales(x.d.db,x.f.core,x.f.cat,casos,x.docs,x.clock);}
 @AfterEach void close()throws Exception{if(x!=null)x.close();}
 long count(String t){return x.d.db.sql.queryForObject("SELECT COUNT(*) FROM "+t,Long.class);}
 void denied(int status,Runnable work){assertEquals(status,assertThrows(FalloTecnico.class,work::run).status);}
 AsociacionesDocumentales.Vista cambio(UUID doc,long rev,List<String> keys){return service.rectificar(x.f.a(x.f.profA),x.key(),"REQ",x.req,doc,new AsociacionesDocumentales.Rectificar(rev,keys,"Rectificación explícita sintética"));}
 @Test void retirarNoEliminaOriginalNiReservaYElResponsablePuedeRestaurarConHistoria()throws Exception{
  UUID doc=x.cargar().id();var original=x.d.db.sql.queryForMap("SELECT * FROM institution_document WHERE id=?",doc.toString());var links=x.d.db.sql.queryForList("SELECT * FROM requirement_document_link");x.docs.proteger(x.f.a(x.f.headA),x.key(),x.req,doc,new DocumentosRequerimiento.Proteccion(0,"FIR","Reserva explícita"));
  var before=x.docs.referencia(x.f.a(x.f.profA),x.req,doc,"CONTENIDO");var body=new AsociacionesDocumentales.Rectificar(-1,List.of(),"Documento incorporado al contexto incorrecto");UUID key=x.key();var withdrawn=service.rectificar(x.f.a(x.f.profA),key,"REQ",x.req,doc,body);assertEquals("RETIRADA",withdrawn.estado());assertEquals(List.of("REQ"),withdrawn.historial().getFirst().anteriores());assertTrue(withdrawn.asociaciones().isEmpty());
  assertEquals(withdrawn,service.rectificar(x.f.a(x.f.profA),key,"REQ",x.req,doc,body));assertEquals(1,count("document_association_command"));var info=x.docs.listar(x.f.a(x.f.headA),x.req).documentos().getFirst();assertFalse(info.consultable());assertFalse(info.descargable());assertTrue(info.asociacionRetirada());assertTrue(info.contextos().isEmpty());assertEquals("FIR",info.proteccion());
  for(String op:List.of("CONTENIDO","DESCARGA","HISTORIAL"))denied(404,()->x.docs.referencia(x.f.a(x.f.profA),x.req,doc,op));
  var restored=cambio(doc,0,List.of("REQ"));assertEquals("ACTIVA",restored.estado());assertEquals(2,restored.historial().size());assertArrayEquals(x.bytes().readAllBytes(),Files.readAllBytes(x.docs.verificarArchivo(before)));assertEquals(original,x.d.db.sql.queryForMap("SELECT * FROM institution_document WHERE id=?",doc.toString()));assertEquals(links,x.d.db.sql.queryForList("SELECT * FROM requirement_document_link"));assertEquals("FIR",x.docs.documento(x.f.a(x.f.profA),x.req,doc).proteccion());assertTrue(x.docs.documento(x.f.a(x.f.profA),x.req,doc).consultable());
 }
 @Test void rectificarApuntaSoloAGestionesRealesDelMismoReqYSinFabricarActuacion(){UUID doc=x.cargar().id();long seq=x.gestion();long acts=count("institution_req_action");var changed=cambio(doc,-1,List.of(Long.toString(seq)));assertEquals(List.of(Long.toString(seq)),changed.asociaciones());assertEquals(1,x.docs.documento(x.f.a(x.f.profA),x.req,doc).contextos().size());assertEquals(seq,x.docs.documento(x.f.a(x.f.profA),x.req,doc).contextos().getFirst().gestionSeq());assertEquals(2,count("requirement_document_link"));assertEquals(acts,count("institution_req_action"));assertEquals(0,x.d.db.sql.queryForObject("SELECT COUNT(*) FROM core_case WHERE requirement_id=?",Long.class,x.req.toString()));denied(404,()->cambio(doc,0,List.of(Long.toString(seq+999))));assertEquals(1,count("document_association_history"));}
 @Test void retiradaNoSeEludeMedianteVinculoAntiguoNiReintentoConfirmado(){
  UUID key=x.key();var d=x.docs.cargar(x.f.a(x.f.profA),key,x.req,null,"aporte.txt",x.bytes());long seq=x.gestion();cambio(d.id(),-1,List.of());var retry=x.docs.cargar(x.f.a(x.f.profA),key,x.req,null,"aporte.txt",x.bytes());assertTrue(retry.asociacionRetirada());assertFalse(retry.consultable());denied(404,()->x.docs.vincular(x.f.a(x.f.profA),x.key(),x.req,d.id(),seq));assertEquals(1,count("institution_document"));assertTrue(service.ver(x.f.a(x.f.headA),"REQ",x.req,d.id()).asociaciones().isEmpty());
 }
 @Test void otraAreaTiYOtroReqNoObtienenHistorialNiCorrigen(){UUID doc=x.cargar().id();cambio(doc,-1,List.of());for(String a:List.of(x.f.ti,x.f.profB,x.f.headB,x.f.dist)){denied(404,()->service.ver(x.f.a(a),"REQ",x.req,doc));denied(404,()->service.rectificar(x.f.a(a),x.key(),"REQ",x.req,doc,new AsociacionesDocumentales.Rectificar(0,List.of("REQ"),"No hereda autoridad")));}UUID other=x.nuevoReq();denied(404,()->service.ver(x.f.a(x.f.profA),"REQ",other,doc));assertEquals(1,count("document_association_history"));}
 @Test void idempotenciaVersionYValidacionNoDejanEfectosParciales(){UUID doc=x.cargar().id();UUID key=x.key();var r=new AsociacionesDocumentales.Rectificar(-1,List.of(),"Retirada explícita");service.rectificar(x.f.a(x.f.profA),key,"REQ",x.req,doc,r);denied(409,()->service.rectificar(x.f.a(x.f.profA),key,"REQ",x.req,doc,new AsociacionesDocumentales.Rectificar(-1,List.of("REQ"),"Otra operación")));denied(409,()->cambio(doc,-1,List.of("REQ")));denied(400,()->cambio(doc,0,List.of("REQ","REQ")));denied(400,()->cambio(doc,0,List.of("00")));assertEquals(1,count("document_association_command"));assertEquals(1,count("document_association_history"));assertEquals(0,count("document_association_target"));}
 @Test void rectificacionesConcurrentesConservanUnaRevisionYUnSoloResultado()throws Exception{
  UUID doc=x.cargar().id();long seq=x.gestion();var go=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var fs=new ArrayList<Future<Boolean>>();for(var keys:List.of(List.<String>of(),List.of(Long.toString(seq))))fs.add(pool.submit(()->{go.await();try{cambio(doc,-1,keys);return true;}catch(FalloTecnico e){assertEquals(409,e.status);return false;}}));go.countDown();assertNotEquals(fs.get(0).get(8,TimeUnit.SECONDS),fs.get(1).get(8,TimeUnit.SECONDS));}assertEquals(1,count("document_association_history"));assertEquals(1,count("document_association_command"));assertEquals(0,service.ver(x.f.a(x.f.profA),"REQ",x.req,doc).revision());
 }
 @Test void falloDeHistoriaRevierteProyeccionPoliticaVinculosYComando(){UUID doc=x.cargar().id();long seq=x.gestion();var policy=x.d.db.sql.queryForMap("SELECT * FROM requirement_document_policy WHERE document_id=?",doc.toString());x.d.ddl(sql->sql.execute("ALTER TABLE document_association_history ADD CONSTRAINT asoc_rollback CHECK(revision=99)"));try{var e=assertThrows(org.springframework.dao.DataAccessException.class,()->cambio(doc,-1,List.of(Long.toString(seq))));assertTrue(org.springframework.core.NestedExceptionUtils.getMostSpecificCause(e).getMessage().toLowerCase(Locale.ROOT).contains("asoc_rollback"));}finally{x.d.ddl(sql->sql.execute("ALTER TABLE document_association_history DROP "+(System.getProperty("siger.test.autoridad.mysql")==null?"CONSTRAINT":"CHECK")+" asoc_rollback"));}assertEquals(0,count("document_association_control"));assertEquals(0,count("document_association_target"));assertEquals(0,count("document_association_command"));assertEquals(1,count("requirement_document_link"));assertEquals(policy,x.d.db.sql.queryForMap("SELECT * FROM requirement_document_policy WHERE document_id=?",doc.toString()));}
 @Test void cierreNoEsBorradoYLaRectificacionNoAbreOtroPeriodo(){UUID doc=x.cargar().id();x.f.core.u2().actuar(x.f.a(x.f.headA),x.key(),x.req,new ContratosNucleo.Decision(x.revision(),"Cierre explícito"),true);var req=x.d.db.sql.queryForMap("SELECT * FROM core_requirement WHERE id=?",x.req.toString());cambio(doc,-1,List.of());cambio(doc,0,List.of("REQ"));assertEquals(req,x.d.db.sql.queryForMap("SELECT * FROM core_requirement WHERE id=?",x.req.toString()));assertEquals(0,x.d.db.sql.queryForObject("SELECT COUNT(*) FROM core_case WHERE requirement_id=?",Long.class,x.req.toString()));assertEquals(0,count("institution_req_action"));}
 @Test void equipoNoObtieneDocumentoRetiradoNiSuHistoriaYElPrincipalConservaControl(){
  UUID cas=x.abrir();x.f.otorgar(x.f.profB,"PROFESIONAL","AREA_A");x.f.core.equipo().incorporar(x.f.a(x.f.profA),x.key(),cas,new EquipoCaso.Incorporar(0,x.f.profB,"Colaboración sintética"));UUID doc=casos.cargar(x.f.a(x.f.profA),x.key(),cas,null,"caso.txt",x.bytes()).id();x.f.core.contenidos().proteger(x.f.a(x.f.headA),x.key(),cas,doc,new ContenidoInstitucional.Proteccion(0,"ORDINARIO","Consulta ordinaria del equipo"));assertTrue(casos.documento(x.f.a(x.f.profB),cas,doc).consultable());
  denied(404,()->service.ver(x.f.a(x.f.profB),"CASO",cas,doc));service.rectificar(x.f.a(x.f.profA),x.key(),"CASO",cas,doc,new AsociacionesDocumentales.Rectificar(-1,List.of(),"Original asociado al Caso por error"));assertTrue(casos.listar(x.f.a(x.f.profB),cas).isEmpty());denied(404,()->casos.referencia(x.f.a(x.f.profB),cas,doc,"METADATOS"));denied(404,()->casos.historial(x.f.a(x.f.profB),cas,doc));assertTrue(casos.documento(x.f.a(x.f.headA),cas,doc).asociacionRetirada());denied(404,()->casos.referencia(x.f.a(x.f.profA),cas,doc,"CONTENIDO"));
  service.rectificar(x.f.a(x.f.headA),x.key(),"CASO",cas,doc,new AsociacionesDocumentales.Rectificar(0,List.of("CASO"),"Restauración fundada"));assertTrue(casos.documento(x.f.a(x.f.profB),cas,doc).consultable());assertEquals(1,count("management_document_link"));
 }
 @Test void revocacionDeResponsableNoSeSustituyeConAutoriaNiHistorial(){UUID doc=x.cargar().id();cambio(doc,-1,List.of());var actor=x.f.a(x.f.profA);x.clock.avanzar(1801);denied(403,()->service.ver(actor,"REQ",x.req,doc));denied(403,()->service.rectificar(actor,x.key(),"REQ",x.req,doc,new AsociacionesDocumentales.Rectificar(0,List.of("REQ"),"No conserva acceso por autoría")));assertEquals(1,count("document_association_command"));}
 @Test void cuentaAliasNoHeredaFacultadDeRectificacionDeLaCuentaResponsable()throws Exception{
  UUID doc=x.cargar().id();cambio(doc,-1,List.of());String alias=x.f.user("alias.asociacion");var r=x.d.mapper.readValue(Base64.getDecoder().decode(x.d.db.sql.queryForObject("SELECT signed_payload FROM authority_batch ORDER BY revision DESC LIMIT 1",String.class)),cl.nexbyte.siger.institucional.identidad.AutoridadesInstitucionales.Registro11.class);var bindings=new ArrayList<>(r.vinculos());bindings.add(new cl.nexbyte.siger.institucional.identidad.AutoridadesInstitucionales.Vinculo(alias,"p-"+x.f.profA,x.f.start,x.f.end,ConcesionFixture.huella(x.d.db,alias)));
  x.f.importar(new cl.nexbyte.siger.institucional.identidad.AutoridadesInstitucionales.Registro11("1.1",r.revision()+1,x.clock.instant(),r.expira(),bindings,r.mandatos(),r.areas(),r.ambitos(),r.cambiosArea()));x.f.otorgar(alias,"PROFESIONAL","AREA_A");denied(404,()->service.ver(x.f.a(alias),"REQ",x.req,doc));denied(404,()->service.rectificar(x.f.a(alias),x.key(),"REQ",x.req,doc,new AsociacionesDocumentales.Rectificar(0,List.of("REQ"),"Misma persona no sustituye asignación de cuenta")));assertEquals(1,count("document_association_command"));
 }
 @Test void rectificarActuacionDeCasoNoMueveOriginalNiAdmiteActuacionDeOtroCaso(){
  UUID cas=x.abrir();UUID doc=casos.cargar(x.f.a(x.f.profA),x.key(),cas,null,"act.txt",x.bytes()).id();long rev=x.d.db.sql.queryForObject("SELECT revision FROM core_case WHERE id=?",Long.class,cas.toString());x.f.core.bitacora().registrarCaso(x.f.a(x.f.profA),x.key(),cas,new BitacoraGestion.Registrar("1.0",rev,x.clock.instant().minusSeconds(5),"Gestión real de Caso",null,null));UUID act=x.f.core.caso(x.f.a(x.f.profA),cas).actuaciones().getFirst().id();long acts=count("core_action");
  var v=service.rectificar(x.f.a(x.f.headA),x.key(),"CASO",cas,doc,new AsociacionesDocumentales.Rectificar(-1,List.of(act.toString()),"Corregir referencia a actuación real"));assertEquals(List.of(act.toString()),v.asociaciones());assertEquals(act,casos.documento(x.f.a(x.f.profA),cas,doc).contextos().getFirst().actuacion());assertEquals(2,count("management_document_link"));assertEquals(acts,count("core_action"));denied(404,()->service.rectificar(x.f.a(x.f.profA),x.key(),"CASO",cas,doc,new AsociacionesDocumentales.Rectificar(0,List.of(UUID.randomUUID().toString()),"No admite actuación ajena")));
 }
 @Test void transferenciaPrincipalNoPublicaDocumentosPreviosNiPermiteRectificarDesdeOtroAmbito(){UUID doc=x.cargar().id();cambio(doc,-1,List.of());var t=x.f.core.continuidad().transferir(x.f.a(x.f.headA),x.key(),x.req,new ContinuidadU2.Trasladar(x.revision(),new ContratosNucleo.NuevoDestino("UPR","DEMO_SEDE_A",x.f.headB,"AREA_B"),"Solicitud sintética","Metadatos de evaluación")).id();x.f.core.continuidad().decidirTransferencia(x.f.a(x.f.headB),x.key(),t,new ContinuidadU2.Resolver(0,"ACEPTADA",null,"Aceptación fundada"));denied(404,()->service.ver(x.f.a(x.f.headB),"REQ",x.req,doc));denied(404,()->service.rectificar(x.f.a(x.f.headB),x.key(),"REQ",x.req,doc,new AsociacionesDocumentales.Rectificar(0,List.of("REQ"),"No hereda original anterior")));}
}
